#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <expression>\n", argv[0]);
        return 1;
    }

    int stack[100];
    int top = 0;

    for (int i = 1; i < argc; i++) {
        char *token = argv[i];
        if (token[0] == '+' || token[0] == '-' || token[0] == '*' || token[0] == '/') {
            if (top < 2) {
                printf("ERROR\n");
                return 1;
            }
            int b = stack[top - 1];
            int a = stack[top - 2];
            top -= 2;
            if (token[0] == '+') {
                stack[top++] = a + b;
            } else if (token[0] == '-') {
                stack[top++] = a - b;
            } else if (token[0] == '*') {
                stack[top++] = a * b;
            } else if (token[0] == '/') {
                if (b == 0) {
                    printf("ERROR\n");
                    return 1;
                }
                stack[top++] = a / b;
            }
        } else {
            char *end;
            long num = strtol(token, &end, 10);
            if (*end != '\0') {
                printf("ERROR\n");
                return 1;
            }
            stack[top++] = num;
        }
    }

    if (top != 1) {
        printf("ERROR\n");
        return 1;
    }

    printf("%d\n", stack[0]);
    return 0;
}
